import {expect} from '@playwright/test';
import {imageDigest} from './text-ui.mjs';
export async function exerciseOverlayUI(page,info,lang='zh',route='/#/tools/edit'){
  const t=(zh,en)=>lang==='en'?en:zh,image=page.locator('.edit-image img'),name=await image.getAttribute('alt');
  await page.getByRole('button',{name:t('添加文字','Add text'),exact:true}).click();await page.getByRole('textbox',{name:t('文字内容','Text content'),exact:true}).fill('Overlay 光影');
  const ready=()=>expect(page.locator('[data-text-layer]').first()).toHaveAttribute('aria-disabled','false');await ready();const plain=await imageDigest(image);
  await page.getByRole('button',{name:t('添加蒙层','Add overlay'),exact:true}).click();await page.getByRole('button',{name:new RegExp('^'+t('保存编辑','Save edits'))}).click();await expect(page.getByRole('button',{name:t('保存编辑','Save edits'),exact:true})).toBeEnabled();await page.getByRole('button',{name:t('撤销编辑','Undo edit'),exact:true}).click();await expect(page.locator('.text-layer-list li')).toHaveCount(1);await page.getByRole('button',{name:new RegExp('^'+t('保存编辑','Save edits'))}).click();await expect(page.getByRole('button',{name:t('保存编辑','Save edits'),exact:true})).toBeEnabled();await page.getByRole('button',{name:t('重做编辑','Redo edit'),exact:true}).click();await expect(page.locator('.text-layer-list li')).toHaveCount(2);await page.getByRole('button',{name:t('选择蒙层 ','Select overlay ')+'2',exact:true}).click();const fill=page.getByRole('combobox',{name:t('蒙层填充','Overlay fill'),exact:true}),coverage=page.getByRole('spinbutton',{name:t('覆盖比例','Coverage'),exact:true});await fill.selectOption('solid');await coverage.fill('1');await coverage.blur();await ready();const covered=await imageDigest(image);expect(covered).not.toBe(plain);
  await page.getByRole('button',{name:t('下移一层','Send backward'),exact:true}).click();await ready();await expect.poll(()=>imageDigest(image)).not.toBe(covered);const behind=await imageDigest(image);
  await page.getByRole('button',{name:t('撤销编辑','Undo edit'),exact:true}).click();await expect.poll(()=>imageDigest(image)).toBe(covered);await page.getByRole('button',{name:t('重做编辑','Redo edit'),exact:true}).click();await expect.poll(()=>imageDigest(image)).toBe(behind);
  await page.getByRole('button',{name:t('隐藏蒙层 ','Hide overlay ')+'1',exact:true}).click();await expect.poll(()=>imageDigest(image)).toBe(plain);await page.getByRole('button',{name:t('隐藏蒙层 ','Hide overlay ')+'1',exact:true}).click();await page.getByRole('button',{name:t('锁定蒙层 ','Lock overlay ')+'1',exact:true}).click();await expect(fill).toBeDisabled();await page.getByRole('button',{name:t('锁定蒙层 ','Lock overlay ')+'1',exact:true}).click();await expect(fill).toBeEnabled();
  await page.getByRole('button',{name:t('复制图层','Duplicate layer'),exact:true}).click();await expect(page.locator('.text-layer-list li')).toHaveCount(3);await page.getByRole('button',{name:t('删除蒙层','Delete overlay'),exact:true}).click();await expect(page.locator('.text-layer-list li')).toHaveCount(2);await page.getByRole('button',{name:t('选择蒙层 ','Select overlay ')+'1',exact:true}).click();
  await fill.selectOption('linear');await page.getByRole('button',{name:t('添加色标','Add stop'),exact:true}).click();await expect(page.locator('.overlay-stop')).toHaveCount(3);await coverage.fill('.5');await coverage.blur();await page.getByRole('combobox',{name:t('覆盖起边','Coverage edge'),exact:true}).selectOption('left');await ready();
  await page.getByRole('button',{name:new RegExp('^'+t('保存编辑','Save edits'))}).click();await expect(page.getByRole('button',{name:t('保存编辑','Save edits'),exact:true})).toBeEnabled();await ready();const frozen=await imageDigest(image);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath('overlay-editor.png'),fullPage:true});
  await page.goto(route);await page.reload();await page.locator('.edit-records>div>button').filter({hasText:name}).first().click();await page.getByRole('button',{name:t('选择蒙层 ','Select overlay ')+'1',exact:true}).click();await expect(page.locator('.overlay-stop')).toHaveCount(3);await expect(coverage).toHaveValue('0.5');await expect.poll(()=>imageDigest(image)).toBe(frozen);return {name,frozen};
}
